    assert(exercise7_digitalRoot(0) == 0)
    assert(exercise7_digitalRoot(9875) == 2)
    assert(exercise7_digitalRoot(9) == 9)
    assert(exercise7_digitalRoot(123) == 6)
    println("Exercise 7 passed: exercise7_digitalRoot")

    // Exercise 8: recamanSequence
    assert(exercise8_recamanSequence(1) == List(0))
    assert(exercise8_recamanSequence(10) == List(0, 1, 3, 6, 2, 7, 13, 20, 12, 21))
    println("Exercise 8 passed: exercise8_recamanSequence")

    println("\nAll exercises passed!")
  }
}
